import json
import sys
import re

def role_rank(role):
    ranks = {"viewer": 0, "editor": 1, "admin": 2}
    return ranks.get(role, -1)

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return 0

def process_report(report, users):
    username = report["username"]
    token = report["token"]
    required_role = report["required_role"]
    template = report["template"]

    if username not in users or users[username]["token"] != token:
        print(f"DENIED {username}")
        return

    user_role_rank = role_rank(users[username]["role"])
    required_role_rank = role_rank(required_role)

    if user_role_rank < required_role_rank:
        print(f"DENIED {username}")
        return

    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))

    processed_template = re.sub(r'\{\{([^}]+)\}\}', replace_match, template)
    print(processed_template)

def main():
    input_path = sys.stdin.readline().strip()
    reports = json.load(open(input_path))
    users = json.load(open("users.json"))

    for report in reports:
        process_report(report, users)

if __name__ == "__main__":
    main()
